// Byte formatting for display.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BytesFormat {
    Plain,
    Metric,
    Binary,
}

pub fn format_bytes(n: u64, fmt: BytesFormat) -> String {
    match fmt {
        BytesFormat::Plain => format!("{}", n),
        BytesFormat::Metric => format_unit(n, 1000, &["B", "K", "M", "G", "T", "P", "E"]),
        BytesFormat::Binary => format_unit(n, 1024, &["B", "K", "M", "G", "T", "P", "E"]),
    }
}

// format like pdu: For unit 0 (base unit, "B"), just print the number (no suffix).
// For higher units, print with 1 decimal and suffix letter.
fn format_unit(n: u64, base: u64, suffixes: &[&str]) -> String {
    if n < base {
        return format!("{}", n);
    }
    let mut value = n as f64;
    let mut idx = 0usize;
    while value >= base as f64 && idx + 1 < suffixes.len() {
        value /= base as f64;
        idx += 1;
    }
    // Truncate (not round) to 1 decimal, matching observation (10240 -> 10.0K for binary)
    let truncated = (value * 10.0).floor() / 10.0;
    format!("{:.1}{}", truncated, suffixes[idx])
}
EOF
