// Data tree representation

#[derive(Clone, Debug)]
pub struct Tree {
    pub name: String,
    pub size: u64,
    pub children: Vec<Tree>,
}

impl Tree {
    pub fn new(name: String, size: u64) -> Self {
        Self { name, size, children: Vec::new() }
    }

    /// Sort children by size recursively.
    /// `ascending` is true for bottom-up display (smallest first).
    pub fn sort_recursive(&mut self, ascending: bool) {
        for c in self.children.iter_mut() {
            c.sort_recursive(ascending);
        }
        if ascending {
            self.children.sort_by(|a, b| a.size.cmp(&b.size));
        } else {
            self.children.sort_by(|a, b| b.size.cmp(&a.size));
        }
    }

    /// Prune children whose size ratio relative to `total` is below `min_ratio`.
    pub fn prune_by_ratio(&mut self, total: u64, min_ratio: f64) {
        if min_ratio <= 0.0 { return; }
        self.children.retain(|c| {
            if total == 0 { return true; }
            (c.size as f64) / (total as f64) >= min_ratio
        });
        for c in self.children.iter_mut() {
            c.prune_by_ratio(total, min_ratio);
        }
    }

    /// Limit depth (keep nodes up to `max_depth` relative depth from the root).
    pub fn limit_depth(&mut self, max_depth: u32, current: u32) {
        if current >= max_depth {
            self.children.clear();
            return;
        }
        for c in self.children.iter_mut() {
            c.limit_depth(max_depth, current + 1);
        }
    }
}
