// Filesystem traversal
use std::collections::HashSet;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

use crate::tree::Tree;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Quantity {
    ApparentSize,
    BlockSize,
    BlockCount,
}

#[derive(Debug, Clone)]
pub struct ErrorEntry {
    pub op: String,
    pub path: PathBuf,
    pub err_msg: String,
}

pub struct HardlinkShared {
    pub ino: u64,
    pub size: u64,
    pub links: u64,
    pub paths: Vec<PathBuf>,
}

pub struct Context {
    pub quantity: Quantity,
    pub dedupe_hardlinks: bool,
    pub errors: Vec<ErrorEntry>,
    /// For hardlink tracking: inode -> (size, link_count, paths seen)
    pub hardlinks: std::collections::HashMap<u64, HardlinkShared>,
    /// set of inode already counted once (for dedupe)
    pub counted_inodes: HashSet<u64>,
}

impl Context {
    pub fn new(quantity: Quantity, dedupe_hardlinks: bool) -> Self {
        Self {
            quantity,
            dedupe_hardlinks,
            errors: Vec::new(),
            hardlinks: Default::default(),
            counted_inodes: HashSet::new(),
        }
    }
}

fn metadata_size(meta: &std::fs::Metadata, q: Quantity) -> u64 {
    match q {
        Quantity::ApparentSize => meta.len(),
        Quantity::BlockSize => meta.blocks() * 512,
        Quantity::BlockCount => meta.blocks(),
    }
}

/// Traverse `path` and return a Tree rooted at it. `name` is the display name.
pub fn traverse(path: &Path, name: &str, ctx: &mut Context) -> Tree {
    let meta = match std::fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(e) => {
            ctx.errors.push(ErrorEntry {
                op: "symlink_metadata".into(),
                path: path.to_path_buf(),
                err_msg: format!("{}", e),
            });
            return Tree::new(name.to_string(), 0);
        }
    };

    let size = metadata_size(&meta, ctx.quantity);

    // track hardlinks (files with nlink > 1)
    if meta.is_file() && meta.nlink() > 1 {
        let ino = meta.ino();
        let entry = ctx.hardlinks.entry(ino).or_insert_with(|| HardlinkShared {
            ino,
            size,
            links: meta.nlink(),
            paths: Vec::new(),
        });
        entry.paths.push(path.to_path_buf());
    }

    if meta.is_dir() {
        let mut tree = Tree::new(name.to_string(), size);
        let entries = match std::fs::read_dir(path) {
            Ok(d) => d,
            Err(e) => {
                ctx.errors.push(ErrorEntry {
                    op: "read_dir".into(),
                    path: path.to_path_buf(),
                    err_msg: format!("{}", e),
                });
                return tree;
            }
        };
        let mut total = size;
        for entry in entries {
            let entry = match entry {
                Ok(e) => e,
                Err(e) => {
                    ctx.errors.push(ErrorEntry {
                        op: "read_dir".into(),
                        path: path.to_path_buf(),
                        err_msg: format!("{}", e),
                    });
                    continue;
                }
            };
            let child_path = entry.path();
            let child_name = entry.file_name().to_string_lossy().into_owned();
            let child_tree = traverse(&child_path, &child_name, ctx);
            total = total.saturating_add(child_tree.size);
            tree.children.push(child_tree);
        }
        tree.size = total;
        tree
    } else {
        // For a regular file with hardlinks: if dedupe, only count on first encounter
        let mut effective = size;
        if ctx.dedupe_hardlinks && meta.is_file() && meta.nlink() > 1 {
            let ino = meta.ino();
            if !ctx.counted_inodes.insert(ino) {
                // already counted
                effective = 0;
            }
        }
        Tree::new(name.to_string(), effective)
    }
}
