// Minimal JSON encoder and decoder for pdu data.

use std::fmt::Write;

pub fn escape_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => { let _ = write!(out, "\\u{:04x}", c as u32); }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

// ----- JSON parser (just enough for our purposes) -----

#[derive(Debug)]
pub enum Value {
    Null,
    Bool(bool),
    Number(f64),
    NumberStr(String),
    String(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

pub struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
    line: u32,
    col: u32,
}

pub fn parse(s: &str) -> Result<Value, String> {
    let mut p = Parser { src: s.as_bytes(), pos: 0, line: 1, col: 1 };
    p.skip_ws();
    let v = p.parse_value()?;
    p.skip_ws();
    Ok(v)
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> { self.src.get(self.pos).copied() }
    fn bump(&mut self) {
        if let Some(c) = self.peek() {
            if c == b'\n' { self.line += 1; self.col = 1; } else { self.col += 1; }
            self.pos += 1;
        }
    }
    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' { self.bump(); } else { break; }
        }
    }
    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'{') => self.parse_object(),
            Some(b'[') => self.parse_array(),
            Some(b'"') => self.parse_string().map(Value::String),
            Some(b't') | Some(b'f') => self.parse_bool(),
            Some(b'n') => self.parse_null(),
            Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
            Some(c) => Err(format!("unexpected character '{}' at line {} column {}", c as char, self.line, self.col)),
            None => Err(format!("unexpected end of input at line {} column {}", self.line, self.col)),
        }
    }
    fn parse_object(&mut self) -> Result<Value, String> {
        self.bump(); // '{'
        let mut entries: Vec<(String, Value)> = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') { self.bump(); return Ok(Value::Object(entries)); }
        loop {
            self.skip_ws();
            let k = self.parse_string()?;
            self.skip_ws();
            if self.peek() != Some(b':') {
                return Err(format!("expected ':' at line {} column {}", self.line, self.col));
            }
            self.bump();
            let v = self.parse_value()?;
            entries.push((k, v));
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.bump(); }
                Some(b'}') => { self.bump(); return Ok(Value::Object(entries)); }
                _ => return Err(format!("expected ',' or '}}' at line {} column {}", self.line, self.col)),
            }
        }
    }
    fn parse_array(&mut self) -> Result<Value, String> {
        self.bump(); // '['
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') { self.bump(); return Ok(Value::Array(items)); }
        loop {
            let v = self.parse_value()?;
            items.push(v);
            self.skip_ws();
            match self.peek() {
                Some(b',') => { self.bump(); }
                Some(b']') => { self.bump(); return Ok(Value::Array(items)); }
                _ => return Err(format!("expected ',' or ']' at line {} column {}", self.line, self.col)),
            }
        }
    }
    fn parse_string(&mut self) -> Result<String, String> {
        if self.peek() != Some(b'"') {
            return Err(format!("expected string at line {} column {}", self.line, self.col));
        }
        self.bump();
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err("unterminated string".into()),
                Some(b'"') => { self.bump(); return Ok(out); }
                Some(b'\\') => {
                    self.bump();
                    match self.peek() {
                        Some(b'"') => { out.push('"'); self.bump(); }
                        Some(b'\\') => { out.push('\\'); self.bump(); }
                        Some(b'/') => { out.push('/'); self.bump(); }
                        Some(b'n') => { out.push('\n'); self.bump(); }
                        Some(b't') => { out.push('\t'); self.bump(); }
                        Some(b'r') => { out.push('\r'); self.bump(); }
                        Some(b'b') => { out.push('\u{08}'); self.bump(); }
                        Some(b'f') => { out.push('\u{0C}'); self.bump(); }
                        Some(b'u') => {
                            self.bump();
                            let mut code = 0u32;
                            for _ in 0..4 {
                                match self.peek() {
                                    Some(c) if c.is_ascii_hexdigit() => {
                                        code = code * 16 + (c as char).to_digit(16).unwrap();
                                        self.bump();
                                    }
                                    _ => return Err("bad unicode escape".into()),
                                }
                            }
                            if let Some(c) = char::from_u32(code) { out.push(c); }
                        }
                        _ => return Err("bad escape".into()),
                    }
                }
                Some(c) => { out.push(c as char); self.bump(); }
            }
        }
    }
    fn parse_bool(&mut self) -> Result<Value, String> {
        if self.src[self.pos..].starts_with(b"true") {
            for _ in 0..4 { self.bump(); }
            Ok(Value::Bool(true))
        } else if self.src[self.pos..].starts_with(b"false") {
            for _ in 0..5 { self.bump(); }
            Ok(Value::Bool(false))
        } else {
            Err("invalid bool".into())
        }
    }
    fn parse_null(&mut self) -> Result<Value, String> {
        if self.src[self.pos..].starts_with(b"null") {
            for _ in 0..4 { self.bump(); }
            Ok(Value::Null)
        } else {
            Err("invalid null".into())
        }
    }
    fn parse_number(&mut self) -> Result<Value, String> {
        let start = self.pos;
        if self.peek() == Some(b'-') { self.bump(); }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == b'.' || c == b'e' || c == b'E' || c == b'+' || c == b'-' {
                self.bump();
            } else { break; }
        }
        let s = std::str::from_utf8(&self.src[start..self.pos]).map_err(|_| "bad number".to_string())?;
        let f: f64 = s.parse().map_err(|e: std::num::ParseFloatError| e.to_string())?;
        Ok(Value::Number(f))
    }
    pub fn line(&self) -> u32 { self.line }
    pub fn col(&self) -> u32 { self.col }
}

// Helpers for extraction.
impl Value {
    pub fn as_object(&self) -> Option<&Vec<(String, Value)>> {
        if let Value::Object(o) = self { Some(o) } else { None }
    }
    pub fn get<'a>(&'a self, key: &str) -> Option<&'a Value> {
        if let Value::Object(o) = self {
            for (k, v) in o { if k == key { return Some(v); } }
        }
        None
    }
    pub fn as_str(&self) -> Option<&str> {
        if let Value::String(s) = self { Some(s) } else { None }
    }
    pub fn as_u64(&self) -> Option<u64> {
        if let Value::Number(n) = self { Some(*n as u64) } else { None }
    }
    pub fn as_array(&self) -> Option<&Vec<Value>> {
        if let Value::Array(a) = self { Some(a) } else { None }
    }
}
