// Tree visualizer: produces ASCII-art chart output matching pdu behavior.

use crate::bytes_format::{format_bytes, BytesFormat};
use crate::tree::Tree;

#[derive(Clone, Copy, Debug)]
pub enum BarDirection { LeftToRight, RightToLeft }

#[derive(Clone, Copy, Debug)]
pub enum TraversalOrder { BottomUp, TopDown }

pub struct VisualizerOptions {
    pub bytes_format: BytesFormat,
    pub direction: BarDirection,
    pub order: TraversalOrder,
    pub total_width: usize,
    pub column_width: Option<(usize, usize)>, // tree_width, bar_width
    pub no_sort: bool,
    pub show_bytes: bool, // true for bytes (K/M/...), false for block counts (plain only)
}

#[derive(Clone)]
struct Row {
    size: u64,
    depth: u32,
    name: String,
    has_children_shown: bool,
    // Whether this node is the first-displayed-child of its parent (for bottom-up top, for top-down bottom).
    first_sibling: bool,
    // Whether this node is at root-level in the display (depth 0).
    is_root_row: bool,
    // For each ancestor column (length = depth), whether vertical line passes through this row.
    ancestor_lines: Vec<bool>,
}

pub fn visualize(root: &Tree, opts: &VisualizerOptions) -> String {
    // Sort tree based on order.
    let mut tree = root.clone();
    if !opts.no_sort {
        tree.sort_recursive(matches!(opts.order, TraversalOrder::BottomUp));
    }

    // Build rows in display order, with tree line info.
    let mut rows: Vec<Row> = Vec::new();
    build_rows(&tree, 0, true, &mut Vec::new(), opts.order, &mut rows);

    // Compute size column width.
    let size_strings: Vec<String> = rows.iter()
        .map(|r| format_bytes_for_display(r.size, opts))
        .collect();
    let max_int_width = size_strings.iter().map(|s| int_part_width(s)).max().unwrap_or(0);
    let size_col_width = match opts.bytes_format {
        BytesFormat::Plain => size_strings.iter().map(|s| s.chars().count()).max().unwrap_or(0),
        BytesFormat::Metric | BytesFormat::Binary => {
            if opts.show_bytes { max_int_width + 3 } else {
                // block-count uses plain format
                size_strings.iter().map(|s| s.chars().count()).max().unwrap_or(0)
            }
        }
    };

    // Compute total size (from root)
    let total_size = tree.size;

    // Compute tree column width (max of what each row needs)
    // Row tree content width = 2*depth (indent) + 3 (tree chars: ┌/├/└ + ─ + ┴/┬/─) + name_width
    let max_depth: u32 = rows.iter().map(|r| r.depth).max().unwrap_or(0);
    let max_tree_row_width: usize = rows.iter().map(|r| {
        2 * (r.depth as usize) + 3 + r.name.chars().count()
    }).max().unwrap_or(0);

    // Determine tree_col_width and bar_col_width
    let (tree_col_width, bar_col_width) = if let Some((tw, bw)) = opts.column_width {
        (tw.min(max_tree_row_width), bw)
    } else {
        // Total width = size_col + 1 (sep) + tree_col + 1 (|) + bar_col + 1 (|) + 4 (pct)
        let fixed = size_col_width + 1 + 1 + 1 + 4;
        let remaining = opts.total_width.saturating_sub(fixed);
        // Allocate tree_col = max_tree_row_width (capped), bar = remaining - tree
        let tw = max_tree_row_width.min(remaining.saturating_sub(10).max(max_tree_row_width));
        // Simpler: tw = max_tree_row_width, bar = remaining - tw
        let tw = max_tree_row_width;
        let bw = remaining.saturating_sub(tw);
        (tw, bw)
    };

    // Render
    let mut out = String::new();
    let _ = max_depth; // silence warn
    for (i, row) in rows.iter().enumerate() {
        render_row(&mut out, row, &size_strings[i], size_col_width, max_int_width, tree_col_width, bar_col_width, total_size, opts);
        out.push('\n');
    }
    out
}

fn format_bytes_for_display(size: u64, opts: &VisualizerOptions) -> String {
    if opts.show_bytes {
        format_bytes(size, opts.bytes_format)
    } else {
        format!("{}", size)
    }
}

fn int_part_width(s: &str) -> usize {
    // Width up to the decimal point, or total if no decimal.
    if let Some(idx) = s.find('.') {
        s[..idx].chars().count()
    } else {
        // Find integer width (could have suffix letter for 0-unit... but actually plain integers have no suffix here)
        s.chars().count()
    }
}

