    out.push_str(&pct_str);
}

fn render_size_string(s: &str, max_int_width: usize, size_col_width: usize) -> String {
    // int_part is s up to '.' or end
    let (int_part, rest) = match s.find('.') {
        Some(i) => (&s[..i], &s[i..]),
        None => (s, ""),
    };
    // If the value has a unit letter (K/M/G/T/P/E) at the end and no '.', still treat as integer with suffix? No: in our formatter, integer values don't have unit.
    let mut out = String::new();
    let ip_len = int_part.chars().count();
    if ip_len < max_int_width {
        for _ in 0..(max_int_width - ip_len) { out.push(' '); }
    }
    out.push_str(int_part);
    out.push_str(rest);
    // Pad to size_col_width
    let cur = out.chars().count();
    if cur < size_col_width {
        for _ in 0..(size_col_width - cur) { out.push(' '); }
    }
    out
}

fn render_bar(out: &mut String, size: u64, total: u64, width: usize, dir: BarDirection) {
    if width == 0 { return; }
    if total == 0 { for _ in 0..width { out.push(' '); } return; }
    // How many full '█' cells
    let full = ((size as u128) * (width as u128) / (total as u128)) as usize;
    let full = full.min(width);
    match dir {
        BarDirection::LeftToRight => {
            for _ in 0..full { out.push('█'); }
            for _ in full..width { out.push(' '); }
        }
        BarDirection::RightToLeft => {
            for _ in full..width { out.push(' '); }
            for _ in 0..full { out.push('█'); }
        }
    }
}
