                    // Wait, but my earlier analysis showed rows between siblings have `│` at the siblings' shared column. That's at 2*D where D = sibling's depth. For DESCENDANTS of a later sibling, at row R (depth > D), column 2*D is where ancestor at depth D was — that's accessed by ancestor_open[D] where D < row.depth.
                    // So when rendering descendants of this sibling (i > 0), we need the "line open" at ancestor column D where D == depth of THIS node's children depth == depth_of_node+1 == depth+1 here.
                    // Wait. depth variable here is the CURRENT node (parent of the children being processed). So parent's depth = `depth`. Children's depth = `depth + 1`. The "shared sibling column" of children = 2*(depth+1).
                    // For descendants of later siblings (not first), this column should have `│` passing through. That corresponds to ancestor_open[depth+1] of those descendants.
                    // But we need to set it properly. Let me restructure.
                }
                // Just go render child's subtree first:
                // We'll push ancestor_open with placeholder for the child level after child is in context (during child's subtree).
                ancestor_open.push(false); // at index `depth` (child's level column)
                // Within first child's subtree, ancestor_open[depth] should be false for its descendants.
                // Wait actually "ancestor_open[D]" is indexed by ancestor depth. For descendants at depth K, ancestor_open[0..K].
                // For a descendant at depth K, ancestor_open[depth_of_node] refers to node's depth.
                // Hmm, it's simpler to think of it as: ancestor_open[d] is true if at depth d, the vertical line passes through THIS row.
                //
                // Let me redesign: during child's subtree rendering, set ancestor_open of this node's column:
                //   - For FIRST child's subtree descendants: at column `depth_of_node`, line is NOT open (because first child's ┌ is at top and nothing above in this branch).
                //   - For SUBSEQUENT children's subtrees: at column `depth_of_node+1` (siblings' column, which in their view is their own depth) — yes the vertical line at children's SHARED column is open between first and later siblings.
                //     So for descendants of later children, set `ancestor_open[depth+1] = true`? But that's at depth+1, not depth.
                //
                // OK I realize ancestor_open should be tracking EACH depth level's state. For current level (children at depth+1), the line at column depth+1 is what spans siblings.
                //
                // Let me reimplement with clearer semantics:
                if i > 0 {
                    // For all subsequent children's subtree: at column (depth) (parent's children-column?)
                    // Actually, the vertical line at children's column (2*(depth+1)) passes through rows of:
                    //   - First child's row (┌)
                    //   - Intermediate rows (between siblings) -- rows in between siblings' subtrees would be "next sibling's subtree"
                    //   - Current sibling's row (├)
                    //   - Until the parent's row (┴)
                    // In bottom-up: first child's row comes AT THE END of its subtree. So between first child and subsequent siblings: first child row, then subsequent sibling's subtree, then subsequent sibling's row, etc.
                    // For subsequent sibling's DESCENDANTS (deeper rows), they're between first child row and subsequent sibling's row. At the shared column (depth+1), line should be `│`.
                }
                let _ = is_first;
                ancestor_open.pop(); // undo placeholder
                build_rows(c, depth + 1, is_first, ancestor_open, order, out);
                // After rendering this sibling's subtree:
                // ...
            }
            // After all children, push node itself
            out.push(Row {
                size: node.size,
                depth,
                name: node.name.clone(),
                has_children_shown: has_children,
                first_sibling,
                is_root_row: depth == 0,
                ancestor_lines: ancestor_open.clone(),
            });
        }
        TraversalOrder::TopDown => {
            out.push(Row {
                size: node.size,
                depth,
                name: node.name.clone(),
                has_children_shown: has_children,
                first_sibling,
                is_root_row: depth == 0,
                ancestor_lines: ancestor_open.clone(),
            });
            for (i, c) in node.children.iter().enumerate() {
                let is_first = i == 0;
                build_rows(c, depth + 1, is_first, ancestor_open, order, out);
            }
        }
    }
}

fn render_row(
    out: &mut String,
    row: &Row,
    size_str: &str,
    size_col_width: usize,
    max_int_width: usize,
    tree_col_width: usize,
    bar_col_width: usize,
    total_size: u64,
    opts: &VisualizerOptions,
) {
    // Size column: integer part right-aligned in max_int_width, then fractional/unit or spaces.
    let rendered_size = render_size_string(size_str, max_int_width, size_col_width);
    out.push_str(&rendered_size);
    // Separator + tree indent
    out.push(' ');
    // Indent: 2*depth spaces (with │ if line passes through)
    let mut tree_section = String::new();
    for d in 0..row.depth as usize {
        let ch = row.ancestor_lines.get(d).copied().unwrap_or(false);
        if ch { tree_section.push('│'); tree_section.push(' '); }
        else  { tree_section.push(' '); tree_section.push(' '); }
    }
    // Tree char
    let first = row.first_sibling;
    let corner = if first { '┌' } else { '├' };
    let mid = '─';
    let tail = if row.has_children_shown {
        match opts.order {
            TraversalOrder::BottomUp => '┴',
            TraversalOrder::TopDown => '┬',
        }
    } else { '─' };
    tree_section.push(corner);
    tree_section.push(mid);
    tree_section.push(tail);
    tree_section.push_str(&row.name);
    // Pad tree_section to tree_col_width
    let len = tree_section.chars().count();
    if len < tree_col_width {
        for _ in 0..(tree_col_width - len) { tree_section.push(' '); }
    }
    out.push_str(&tree_section);
    // Bar
    out.push('│');
    render_bar(out, row.size, total_size, bar_col_width, opts.direction);
    out.push('│');
    // Percent
    let pct = if total_size == 0 { 0 } else { ((row.size as u128) * 100 / (total_size as u128)) as u64 };
    let pct_str = format!("{:>3}%", pct);
    out.push_str(&pct_str);
}

fn render_size_string(s: &str, max_int_width: usize, size_col_width: usize) -> String {
    // int_part is s up to '.' or end
    let (int_part, rest) = match s.find('.') {
        Some(i) => (&s[..i], &s[i..]),
        None => (s, ""),
    };
    // If the value has a unit letter (K/M/G/T/P/E) at the end and no '.', still treat as integer with suffix? No: in our formatter, integer values don't have unit.
    let mut out = String::new();
    let ip_len = int_part.chars().count();
    if ip_len < max_int_width {
        for _ in 0..(max_int_width - ip_len) { out.push(' '); }
    }
    out.push_str(int_part);
    out.push_str(rest);
    // Pad to size_col_width
    let cur = out.chars().count();
    if cur < size_col_width {
        for _ in 0..(size_col_width - cur) { out.push(' '); }
    }
    out
}

fn render_bar(out: &mut String, size: u64, total: u64, width: usize, dir: BarDirection) {
    if width == 0 { return; }
    if total == 0 { for _ in 0..width { out.push(' '); } return; }
    // How many full '█' cells
    let full = ((size as u128) * (width as u128) / (total as u128)) as usize;
    let full = full.min(width);
    match dir {
        BarDirection::LeftToRight => {
            for _ in 0..full { out.push('█'); }
            for _ in full..width { out.push(' '); }
        }
        BarDirection::RightToLeft => {
            for _ in full..width { out.push(' '); }
            for _ in 0..full { out.push('█'); }
        }
    }
}
