fn parse_bytes_format(v: &str) -> Result<BytesFormat, String> {
    match v {
        "plain" => Ok(BytesFormat::Plain),
        "metric" => Ok(BytesFormat::Metric),
        "binary" => Ok(BytesFormat::Binary),
        _ => Err(format!(
            "invalid value '{}' for '--bytes-format <BYTES_FORMAT>'\n  [possible values: plain, metric, binary]",
            v
        )),
    }
}

fn parse_quantity(v: &str) -> Result<Quantity, String> {
    match v {
        "apparent-size" => Ok(Quantity::ApparentSize),
        "block-size" => Ok(Quantity::BlockSize),
        "block-count" => Ok(Quantity::BlockCount),
        _ => Err(format!(
            "invalid value '{}' for '--quantity <QUANTITY>'\n  [possible values: apparent-size, block-size, block-count]",
            v
        )),
    }
}

fn parse_max_depth(v: &str) -> Result<u32, String> {
    if v == "inf" { return Ok(u32::MAX); }
    match v.parse::<u32>() {
        Ok(0) => Err(format!(
            "invalid value '{}' for '--max-depth <MAX_DEPTH>': Value is neither \"inf\" nor a positive integer: number would be zero for non-zero type",
            v
        )),
        Ok(n) => Ok(n),
        Err(e) => Err(format!(
            "invalid value '{}' for '--max-depth <MAX_DEPTH>': Value is neither \"inf\" nor a positive integer: {}",
            v, e
        )),
    }
}

fn parse_min_ratio(v: &str) -> Result<f64, String> {
    let f: f64 = v.parse().map_err(|_| format!(
        "invalid value '{}' for '--min-ratio <MIN_RATIO>': invalid float literal", v))?;
    if f.is_nan() {
        return Err(format!("invalid value '{}' for '--min-ratio <MIN_RATIO>': NaN", v));
    }
    if f >= 1.0 {
        return Err(format!("invalid value '{}' for '--min-ratio <MIN_RATIO>': greater than or equal to 1", v));
    }
    if f < 0.0 {
        return Err(format!("invalid value '{}' for '--min-ratio <MIN_RATIO>': less than 0", v));
    }
    Ok(f)
}

fn parse_total_width(v: &str) -> Result<usize, String> {
    v.parse::<usize>().map_err(|e| format!(
        "invalid value '{}' for '--total-width <TOTAL_WIDTH>': {}", v, e))
}

fn parse_args(raw: Vec<String>) -> Result<Args, String> {
    let mut args = Args::default();
    let mut i = 1usize; // skip program name
    let mut positional = Vec::new();
    let mut only_positional = false;
    while i < raw.len() {
        let a = &raw[i];
        if only_positional {
            positional.push(a.clone());
            i += 1;
            continue;
        }
        match a.as_str() {
            "--" => { only_positional = true; i += 1; }
            "-h" => { print_help_short(); std::process::exit(0); }
            "--help" => { print_help_long(); std::process::exit(0); }
            "-V" | "--version" => { print_version(); std::process::exit(0); }
            "--json-input" => { args.json_input = true; i += 1; }
            "--json-output" => { args.json_output = true; i += 1; }
            "--top-down" => { args.top_down = true; i += 1; }
            "--align-right" => { args.align_right = true; i += 1; }
            "--no-sort" => { args.no_sort = true; i += 1; }
            "-s" | "--silent-errors" | "--no-errors" => { args.silent_errors = true; i += 1; }
            "-p" | "--progress" => { args.progress = true; i += 1; }
            "-H" | "--deduplicate-hardlinks" | "--detect-links" | "--dedupe-links" => {
                args.dedupe_hardlinks = true; i += 1;
            }
            "--omit-json-shared-details" => { args.omit_json_shared_details = true; i += 1; }
            "--omit-json-shared-summary" => { args.omit_json_shared_summary = true; i += 1; }
            "-b" | "--bytes-format" => {
                let v = raw.get(i+1).ok_or_else(|| "missing value".to_string())?;
                args.bytes_format = parse_bytes_format(v)?;
                i += 2;
            }
            s if s.starts_with("--bytes-format=") => {
                args.bytes_format = parse_bytes_format(&s["--bytes-format=".len()..])?;
                i += 1;
            }
            "-q" | "--quantity" => {
                let v = raw.get(i+1).ok_or_else(|| "missing value".to_string())?;
                args.quantity = parse_quantity(v)?;
                i += 2;
            }
            s if s.starts_with("--quantity=") => {
                args.quantity = parse_quantity(&s["--quantity=".len()..])?;
                i += 1;
            }
            "-d" | "--max-depth" | "--depth" => {
                let v = raw.get(i+1).ok_or_else(|| "missing value".to_string())?;
                args.max_depth = parse_max_depth(v)?;
                i += 2;
            }
            s if s.starts_with("--max-depth=") => {
                args.max_depth = parse_max_depth(&s["--max-depth=".len()..])?;
                i += 1;
            }
            s if s.starts_with("--depth=") => {
                args.max_depth = parse_max_depth(&s["--depth=".len()..])?;
                i += 1;
            }
            "-w" | "--total-width" | "--width" => {
                let v = raw.get(i+1).ok_or_else(|| "missing value".to_string())?;
                args.total_width = Some(parse_total_width(v)?);
                i += 2;
            }
            s if s.starts_with("--total-width=") => {
                args.total_width = Some(parse_total_width(&s["--total-width=".len()..])?);
                i += 1;
            }
            s if s.starts_with("--width=") => {
                args.total_width = Some(parse_total_width(&s["--width=".len()..])?);
                i += 1;
            }
            "--column-width" => {
                let a1 = raw.get(i+1).ok_or_else(|| "missing value".to_string())?;
                let a2 = raw.get(i+2).ok_or_else(|| "missing value".to_string())?;
                let t: usize = a1.parse().map_err(|_| format!("invalid column width '{}'", a1))?;
                let b: usize = a2.parse().map_err(|_| format!("invalid column width '{}'", a2))?;
                args.column_width = Some((t, b));
                i += 3;
            }
            "-m" | "--min-ratio" => {
                let v = raw.get(i+1).ok_or_else(|| "missing value".to_string())?;
                args.min_ratio = parse_min_ratio(v)?;
                i += 2;
            }
            s if s.starts_with("--min-ratio=") => {
                args.min_ratio = parse_min_ratio(&s["--min-ratio=".len()..])?;
                i += 1;
            }
            "--threads" => {
                let v = raw.get(i+1).ok_or_else(|| "missing value".to_string())?;
                args.threads = v.clone();
                i += 2;
            }
            s if s.starts_with("--threads=") => {
                args.threads = s["--threads=".len()..].to_string();
                i += 1;
            }
            s if s.starts_with("--") => {
                return Err(format!("unexpected argument '{}'", s));
            }
            s if s.starts_with("-") && s.len() > 1 && s != "-" => {
                // Could be a combined short flag — try to split
                let mut j = 1usize;
                let bytes = s.as_bytes();
                while j < bytes.len() {
                    let c = bytes[j];
                    match c {
                        b'H' => { args.dedupe_hardlinks = true; }
                        b's' => { args.silent_errors = true; }
                        b'p' => { args.progress = true; }
                        b'h' => { print_help_short(); std::process::exit(0); }
                        b'V' => { print_version(); std::process::exit(0); }
                        _ => {
                            return Err(format!("unexpected argument '{}'", s));
                        }
                    }
                    j += 1;
                }
                i += 1;
            }
            _ => {
                positional.push(a.clone());
                i += 1;
            }
        }
    }
    for p in positional { args.files.push(PathBuf::from(p)); }
    Ok(args)
}

pub fn run() -> Result<u8, String> {
    let raw: Vec<String> = std::env::args().collect();
    let args = match parse_args(raw) {
        Ok(a) => a,
        Err(msg) => {
            eprintln!("error: {}\n\nFor more information, try '--help'.", msg);
            return Ok(2);
        }
    };

    // Emit two carriage returns to stderr (progress spinner clear) — matches observed behavior.
    let _ = std::io::stderr().write_all(b"\r\r");

    let tree = if args.json_input {
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf).map_err(|e| e.to_string())?;
        match parse_json_input(&buf) {
            Ok(t) => t,
            Err(msg) => {
                eprintln!("[error] DeserializationFailure: {}", msg);
                return Ok(3);
            }
        }
    } else {
        build_tree_from_paths(&args)?
    };

    let mut tree = tree;
    // min_ratio: prune
    let total = tree.size;
    tree.prune_by_ratio(total, args.min_ratio);
    // limit depth
    if args.max_depth != u32::MAX {
        tree.limit_depth(args.max_depth, 0);
    }

    // Output
    if args.json_output {
        let unit = if matches!(args.quantity, Quantity::BlockCount) && !args.json_input {
            "blocks"
        } else {
            "bytes"
        };
        let json = encode_tree(&tree, unit, &args);
        print!("{}", json);
    } else {
        let total_width = args.total_width.unwrap_or_else(detect_terminal_width);
        let opts = VisualizerOptions {
            bytes_format: args.bytes_format,
            direction: if args.align_right { BarDirection::RightToLeft } else { BarDirection::LeftToRight },
            order: if args.top_down { TraversalOrder::TopDown } else { TraversalOrder::BottomUp },
            total_width,
            column_width: args.column_width,
            no_sort: args.no_sort,
            show_bytes: !matches!(args.quantity, Quantity::BlockCount),
        };
        let s = visualize(&tree, &opts);
        print!("{}", s);
    }

    Ok(0)
}

fn detect_terminal_width() -> usize {
    // Try to detect via TIOCGWINSZ; default 150.
    #[cfg(target_os = "linux")]
    {
        use std::os::unix::io::AsRawFd;
        #[repr(C)]
        struct WinSize { ws_row: u16, ws_col: u16, ws_xpixel: u16, ws_ypixel: u16 }
        extern "C" {
            fn ioctl(fd: i32, request: u64, ...) -> i32;
        }
        const TIOCGWINSZ: u64 = 0x5413;
        let mut ws = WinSize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
        let stderr = std::io::stderr();
        let fd = stderr.as_raw_fd();
        let rc = unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) };
        if rc == 0 && ws.ws_col > 0 {
            return ws.ws_col as usize;
        }
    }
    150
}

fn build_tree_from_paths(args: &Args) -> Result<Tree, String> {
    let paths: Vec<PathBuf> = if args.files.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        args.files.clone()
    };
    let mut ctx = TCtx::new(args.quantity, args.dedupe_hardlinks);
    let mut roots: Vec<Tree> = Vec::new();
    for p in &paths {
        let name = p.to_string_lossy().into_owned();
        let t = traverse(p, &name, &mut ctx);
        roots.push(t);
    }
    // Emit collected errors
    if !args.silent_errors {
        for e in &ctx.errors {
            eprintln!("[error] {} {:?}: {}", e.op, e.path.to_string_lossy(), e.err_msg);
        }
    }
    let tree = if roots.len() == 1 {
        roots.into_iter().next().unwrap()
    } else {
        let total: u64 = roots.iter().map(|r| r.size).sum();
        Tree { name: "(total)".into(), size: total, children: roots }
    };
    Ok(tree)
}

fn encode_tree(tree: &Tree, unit: &str, _args: &Args) -> String {
    let mut out = String::new();
    out.push_str("{\"schema-version\":");
    out.push_str(&json::escape_str(SCHEMA_VERSION));
    out.push_str(",\"pdu\":");
    out.push_str(&json::escape_str(PDU_VERSION));
    out.push_str(",\"unit\":");
    out.push_str(&json::escape_str(unit));
    out.push_str(",\"tree\":");
    encode_node(&mut out, tree);
    out.push('}');
    out
}

fn encode_node(out: &mut String, node: &Tree) {
    out.push_str("{\"name\":");
    out.push_str(&json::escape_str(&node.name));
    out.push_str(",\"size\":");
    out.push_str(&node.size.to_string());
    out.push_str(",\"children\":[");
    for (i, c) in node.children.iter().enumerate() {
        if i > 0 { out.push(','); }
        encode_node(out, c);
    }
    out.push_str("]}");
}

fn parse_json_input(s: &str) -> Result<Tree, String> {
    let v = json::parse(s).map_err(|e| e.to_string())?;
    // Require schema-version field at top-level
    let root_obj = v.as_object().ok_or_else(|| "expected JSON object".to_string())?;
    if !root_obj.iter().any(|(k, _)| k == "schema-version") {
        // Compute location of root object
        return Err("missing field `schema-version` at line 1 column 2".into());
    }
    let tree_v = v.get("tree").ok_or_else(|| "missing field `tree`".to_string())?;
    let t = json_to_tree(tree_v)?;
    Ok(t)
}

fn json_to_tree(v: &json::Value) -> Result<Tree, String> {
    let name = v.get("name").and_then(|x| x.as_str()).unwrap_or("").to_string();
    let size = v.get("size").and_then(|x| x.as_u64()).unwrap_or(0);
    let mut children: Vec<Tree> = Vec::new();
    if let Some(arr) = v.get("children").and_then(|x| x.as_array()) {
        for c in arr {
            children.push(json_to_tree(c)?);
        }
    }
    // Recompute size = own + children; but keep as-is and let visualizer handle.
    let total = children.iter().map(|c| c.size).sum::<u64>() + size;
    // Actually the JSON input already has computed totals; sum ≠ reported size typically.
    // Use reported size if children are empty; else compute from children.
    let final_size = if children.is_empty() { size } else { total };
    Ok(Tree { name, size: final_size, children })
