    out.push_str(",\"children\":[");
    for (i, c) in node.children.iter().enumerate() {
        if i > 0 { out.push(','); }
        encode_node(out, c);
    }
    out.push_str("]}");
}

fn parse_json_input(s: &str) -> Result<Tree, String> {
    let v = json::parse(s).map_err(|e| e.to_string())?;
    // Require schema-version field at top-level
    let root_obj = v.as_object().ok_or_else(|| "expected JSON object".to_string())?;
    if !root_obj.iter().any(|(k, _)| k == "schema-version") {
        // Compute location of root object
        return Err("missing field `schema-version` at line 1 column 2".into());
    }
    let tree_v = v.get("tree").ok_or_else(|| "missing field `tree`".to_string())?;
    let t = json_to_tree(tree_v)?;
    Ok(t)
}

fn json_to_tree(v: &json::Value) -> Result<Tree, String> {
    let name = v.get("name").and_then(|x| x.as_str()).unwrap_or("").to_string();
    let size = v.get("size").and_then(|x| x.as_u64()).unwrap_or(0);
    let mut children: Vec<Tree> = Vec::new();
    if let Some(arr) = v.get("children").and_then(|x| x.as_array()) {
        for c in arr {
            children.push(json_to_tree(c)?);
        }
    }
    // Recompute size = own + children; but keep as-is and let visualizer handle.
    let total = children.iter().map(|c| c.size).sum::<u64>() + size;
    // Actually the JSON input already has computed totals; sum ≠ reported size typically.
    // Use reported size if children are empty; else compute from children.
    let final_size = if children.is_empty() { size } else { total };
    Ok(Tree { name, size: final_size, children })
}
