// Tree visualizer: produces ASCII-art chart output matching pdu behavior.

use crate::bytes_format::{format_bytes, BytesFormat};
use crate::tree::Tree;

#[derive(Clone, Copy, Debug)]
pub enum BarDirection { LeftToRight, RightToLeft }

#[derive(Clone, Copy, Debug)]
pub enum TraversalOrder { BottomUp, TopDown }

pub struct VisualizerOptions {
    pub bytes_format: BytesFormat,
    pub direction: BarDirection,
    pub order: TraversalOrder,
    pub total_width: usize,
    pub column_width: Option<(usize, usize)>,
    pub no_sort: bool,
    pub show_bytes: bool,
}

// Position among siblings in display order.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SibPos {
    OnlyOrFirst,
    Middle,
    Last,
    Alone, // only child (both first and last)
    Root,  // top-level (no parent)
}

#[derive(Clone)]
struct Row {
    size: u64,
    depth: u32,
    name: String,
    has_children_shown: bool,
    sib_pos: SibPos,
    // For each ancestor column d in [0, depth), whether vertical line passes through this row.
    ancestor_lines: Vec<bool>,
}

pub fn visualize(root: &Tree, opts: &VisualizerOptions) -> String {
    let mut tree = root.clone();
    if !opts.no_sort {
        tree.sort_recursive(matches!(opts.order, TraversalOrder::BottomUp));
    }

    let mut rows: Vec<Row> = Vec::new();
    let mut line_open: Vec<bool> = Vec::new();
    build_rows(&tree, 0, SibPos::Root, &mut line_open, opts.order, &mut rows);

    // size strings for formatting
    let size_strings: Vec<String> = rows.iter()
        .map(|r| format_value(r.size, opts))
        .collect();
    let max_int_width = size_strings.iter().map(|s| int_part_width(s)).max().unwrap_or(0);

    let (size_col_width, add_decimal_reserve) = match (opts.bytes_format, opts.show_bytes) {
        (BytesFormat::Plain, _) | (_, false) => {
            (size_strings.iter().map(|s| s.chars().count()).max().unwrap_or(0), false)
        }
        (BytesFormat::Metric, _) | (BytesFormat::Binary, _) => {
            (max_int_width + 3, true)
        }
    };

    let total_size = rows.iter()
        .filter(|r| matches!(r.sib_pos, SibPos::Root))
        .map(|r| r.size)
        .max()
        .unwrap_or_else(|| tree.size);

    let max_tree_row_width: usize = rows.iter().map(|r| {
        2 * (r.depth as usize) + 3 + r.name.chars().count()
    }).max().unwrap_or(0);

    let (tree_col_width, bar_col_width) = if let Some((tw, bw)) = opts.column_width {
        (tw.min(max_tree_row_width), bw)
    } else {
        let fixed = size_col_width + 1 + 1 + 1 + 4;
        let remaining = opts.total_width.saturating_sub(fixed);
        let tw = max_tree_row_width;
        let bw = remaining.saturating_sub(tw);
        (tw, bw)
    };

    let mut out = String::new();
    for (i, row) in rows.iter().enumerate() {
        render_row(&mut out, row, &size_strings[i], size_col_width, max_int_width, add_decimal_reserve, tree_col_width, bar_col_width, total_size, opts);
        out.push('\n');
    }
    out
}

fn format_value(size: u64, opts: &VisualizerOptions) -> String {
    if opts.show_bytes {
        format_bytes(size, opts.bytes_format)
    } else {
        format!("{}", size)
    }
}

fn int_part_width(s: &str) -> usize {
    if let Some(idx) = s.find('.') {
        s[..idx].chars().count()
    } else {
        s.chars().count()
    }
}

fn build_rows(
    node: &Tree,
    depth: u32,
    sib_pos: SibPos,
    line_open: &mut Vec<bool>,
    order: TraversalOrder,
    out: &mut Vec<Row>,
) {
    let has_children = !node.children.is_empty();
    let n = node.children.len();
    while line_open.len() <= depth as usize { line_open.push(false); }

    match order {
        TraversalOrder::BottomUp => {
            // Render all children's subtrees first, then this node.
            while line_open.len() <= (depth + 1) as usize { line_open.push(false); }
            for i in 0..n {
                // Before rendering child i's subtree: set line_open[depth+1]
                // In bottom-up: line is open at (depth+1) col for descendants of children that are AFTER the first displayed child.
                // First child (i==0): line NOT open.
                // Subsequent (i>0): line is open.
                line_open[depth as usize + 1] = i > 0;
                let cpos = if n == 1 {
                    SibPos::OnlyOrFirst
                } else if i == 0 {
                    SibPos::OnlyOrFirst
                } else if i == n - 1 {
                    SibPos::Last
                } else {
                    SibPos::Middle
                };
                build_rows(&node.children[i], depth + 1, cpos, line_open, order, out);
            }
            line_open[depth as usize + 1] = false;
            // Push self row with ancestor_lines = line_open[0..depth]
            out.push(Row {
                size: node.size,
                depth,
                name: node.name.clone(),
                has_children_shown: has_children,
                sib_pos,
                ancestor_lines: line_open[0..depth as usize].to_vec(),
            });
        }
        TraversalOrder::TopDown => {
            // Push self first, then children.
            out.push(Row {
                size: node.size,
                depth,
                name: node.name.clone(),
                has_children_shown: has_children,
                sib_pos,
                ancestor_lines: line_open[0..depth as usize].to_vec(),
            });
            while line_open.len() <= (depth + 1) as usize { line_open.push(false); }
            for i in 0..n {
                // While rendering Ci's subtree: line_open[depth+1] = TRUE iff there are siblings AFTER Ci (not last).
                line_open[depth as usize + 1] = i < n - 1;
                let cpos = if n == 1 {
                    SibPos::OnlyOrFirst
                } else if i == 0 {
                    SibPos::OnlyOrFirst
                } else if i == n - 1 {
                    SibPos::Last
                } else {
                    SibPos::Middle
                };
                build_rows(&node.children[i], depth + 1, cpos, line_open, order, out);
            }
            line_open[depth as usize + 1] = false;
        }
    }
}

fn render_row(
    out: &mut String,
    row: &Row,
    size_str: &str,
    size_col_width: usize,
    max_int_width: usize,
    _decimal_reserve: bool,
    tree_col_width: usize,
    bar_col_width: usize,
    total_size: u64,
    opts: &VisualizerOptions,
) {
    let rendered_size = render_size_string(size_str, max_int_width, size_col_width);
    out.push_str(&rendered_size);
    out.push(' ');
    let mut tree_section = String::new();
    for d in 0..row.depth as usize {
        let ch = row.ancestor_lines.get(d).copied().unwrap_or(false);
        if ch { tree_section.push('│'); tree_section.push(' '); }
        else  { tree_section.push(' '); tree_section.push(' '); }
    }
    // Tree char: depends on SibPos and order.
    let (corner, mid, tail) = tree_chars(row, opts);
    tree_section.push(corner);
    tree_section.push(mid);
    tree_section.push(tail);
    tree_section.push_str(&row.name);
    let len = tree_section.chars().count();
    if len < tree_col_width {
        for _ in 0..(tree_col_width - len) { tree_section.push(' '); }
    }
    out.push_str(&tree_section);
    out.push('│');
    render_bar(out, row.size, total_size, bar_col_width, opts.direction);
    out.push('│');
    let pct = if total_size == 0 { 0 } else { ((row.size as u128) * 100 / (total_size as u128)) as u64 };
    let pct_str = format!("{:>3}%", pct);
    out.push_str(&pct_str);
}

fn tree_chars(row: &Row, opts: &VisualizerOptions) -> (char, char, char) {
    let has_children = row.has_children_shown;
    let corner = match (opts.order, row.sib_pos) {
        // Bottom-up: first/top → ┌, middle/last → ├, root → ┌
        (TraversalOrder::BottomUp, SibPos::OnlyOrFirst) | (TraversalOrder::BottomUp, SibPos::Alone) => '┌',
        (TraversalOrder::BottomUp, SibPos::Root) => '┌',
        (TraversalOrder::BottomUp, SibPos::Middle) | (TraversalOrder::BottomUp, SibPos::Last) => '├',
        // Top-down: last → └, first/middle → ├, root → └
        (TraversalOrder::TopDown, SibPos::Root) => '└',
        (TraversalOrder::TopDown, SibPos::Last) | (TraversalOrder::TopDown, SibPos::Alone) => '└',
        (TraversalOrder::TopDown, SibPos::OnlyOrFirst) | (TraversalOrder::TopDown, SibPos::Middle) => '├',
    };
    let mid = '─';
    let tail = if has_children {
        match opts.order {
            TraversalOrder::BottomUp => '┴',
            TraversalOrder::TopDown => '┬',
        }
    } else { '─' };
    (corner, mid, tail)
}

fn render_size_string(s: &str, max_int_width: usize, size_col_width: usize) -> String {
    let (int_part, rest) = match s.find('.') {
        Some(i) => (&s[..i], &s[i..]),
        None => (s, ""),
    };
    let mut out = String::new();
    let ip_len = int_part.chars().count();
    if ip_len < max_int_width {
        for _ in 0..(max_int_width - ip_len) { out.push(' '); }
    }
    out.push_str(int_part);
    out.push_str(rest);
    let cur = out.chars().count();
    if cur < size_col_width {
        for _ in 0..(size_col_width - cur) { out.push(' '); }
    }
    out
}

fn render_bar(out: &mut String, size: u64, total: u64, width: usize, dir: BarDirection) {
    if width == 0 { return; }
    if total == 0 { for _ in 0..width { out.push(' '); } return; }
    let full = ((size as u128) * (width as u128) / (total as u128)) as usize;
    let full = full.min(width);
    match dir {
        BarDirection::LeftToRight => {
            for _ in 0..full { out.push('█'); }
            for _ in full..width { out.push(' '); }
        }
        BarDirection::RightToLeft => {
            for _ in full..width { out.push(' '); }
            for _ in 0..full { out.push('█'); }
        }
    }
}
