#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BytesFormat {
    Plain,
    Metric,
    Binary,
}

pub fn format_bytes(n: u64, fmt: BytesFormat) -> String {
    match fmt {
        BytesFormat::Plain => format!("{}", n),
        BytesFormat::Metric => format_unit(n, 1000, &["B", "K", "M", "G", "T", "P", "E"]),
        BytesFormat::Binary => format_unit(n, 1024, &["B", "K", "M", "G", "T", "P", "E"]),
    }
}

fn format_unit(n: u64, base: u64, suffixes: &[&str]) -> String {
    if n < base {
        return format!("{}", n);
    }
    let mut value = n as f64;
    let mut idx = 0usize;
    while value >= base as f64 && idx + 1 < suffixes.len() {
        value /= base as f64;
        idx += 1;
    }
    // Check if rounding would push to next unit
    let formatted = format!("{:.1}", value);
    let would_equal_base = formatted.parse::<f64>().map(|f| f >= base as f64).unwrap_or(false);
    if would_equal_base && idx + 1 < suffixes.len() {
        value /= base as f64;
        idx += 1;
    }
    format!("{:.1}{}", value, suffixes[idx])
}
