// Filesystem traversal
use std::collections::HashMap;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

use crate::tree::Tree;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Quantity {
    ApparentSize,
    BlockSize,
    BlockCount,
}

#[derive(Debug, Clone)]
pub struct ErrorEntry {
    pub op: String,
    pub path: PathBuf,
    pub err_msg: String,
}

#[derive(Clone, Debug)]
pub struct HardlinkInfo {
    pub ino: u64,
    pub size: u64,
    pub links: u64, // nlink
    pub paths: Vec<PathBuf>,
}

pub struct Context {
    pub quantity: Quantity,
    pub dedupe_hardlinks: bool,
    pub errors: Vec<ErrorEntry>,
    /// Inode -> seen info
    pub hardlinks: HashMap<u64, HardlinkInfo>,
}

impl Context {
    pub fn new(quantity: Quantity, dedupe_hardlinks: bool) -> Self {
        Self {
            quantity,
            dedupe_hardlinks,
            errors: Vec::new(),
            hardlinks: HashMap::new(),
        }
    }
}

fn metadata_size(meta: &std::fs::Metadata, q: Quantity) -> u64 {
    match q {
        Quantity::ApparentSize => meta.len(),
        Quantity::BlockSize => meta.blocks() * 512,
        Quantity::BlockCount => meta.blocks(),
    }
}

/// Traverse `path` and return (Tree, contribution).
pub fn traverse(path: &Path, name: &str, ctx: &mut Context) -> (Tree, u64) {
    let meta = match std::fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(e) => {
            ctx.errors.push(ErrorEntry {
                op: "symlink_metadata".into(),
                path: path.to_path_buf(),
                err_msg: format!("{}", e),
            });
            return (Tree::new(name.to_string(), 0), 0);
        }
    };

