            ino,
            size: self_size,
            links: meta.nlink(),
            paths: Vec::new(),
        });
        let already_seen = !entry.paths.is_empty();
        entry.paths.push(path.to_path_buf());
        if ctx.dedupe_hardlinks && already_seen {
            contribution = 0;
        } else {
            contribution = self_size;
        }
    } else {
        contribution = self_size;
    }

    if meta.is_dir() {
        let mut tree = Tree::new(name.to_string(), self_size);
        let entries = match std::fs::read_dir(path) {
            Ok(d) => d,
            Err(e) => {
                ctx.errors.push(ErrorEntry {
                    op: "read_dir".into(),
                    path: path.to_path_buf(),
                    err_msg: format!("{}", e),
                });
                return (tree, contribution);
            }
        };
        let mut total = self_size;
        for entry in entries {
            let entry = match entry {
                Ok(e) => e,
                Err(e) => {
                    ctx.errors.push(ErrorEntry {
                        op: "read_dir".into(),
                        path: path.to_path_buf(),
                        err_msg: format!("{}", e),
                    });
                    continue;
                }
            };
            let child_path = entry.path();
            let child_name = entry.file_name().to_string_lossy().into_owned();
            let (child_tree, child_contrib) = traverse(&child_path, &child_name, ctx);
            total = total.saturating_add(child_contrib);
            tree.children.push(child_tree);
        }
        tree.size = total;
        (tree, total)
    } else {
        (Tree::new(name.to_string(), self_size), contribution)
    }
}
